package io.github.diodeme.ji.telemetry;

import java.util.Map;

/** Name and start attributes for one callback-owned span. */
public record SpanSpec(String name, Map<String, TelemetryValue> attributes) {
    public SpanSpec {
        if (name == null || name.isBlank()) throw new IllegalArgumentException("span name must not be blank");
        attributes = Map.copyOf(attributes);
    }

    public static SpanSpec named(String name) {
        return new SpanSpec(name, Map.of());
    }
}
